const day = (n) => new Date(Date.now() + n * 86400000).toISOString().slice(0, 10);
pm.collectionVariables.set("availFrom", day(-1));
pm.collectionVariables.set("availUntil", day(120));
pm.collectionVariables.set("checkIn", day(5));
pm.collectionVariables.set("checkOut", day(8));
pm.collectionVariables.set("overlapIn", day(6));
pm.collectionVariables.set("overlapOut", day(9));
pm.collectionVariables.set("listingTitle", "Postman Annex " + Date.now());

pm.test("Status code is 201", () => pm.response.to.have.status(201));
const listing = pm.response.json();
pm.test("New listing is pending", () => {
  pm.expect(listing.status).to.eql("pending");
  pm.expect(listing.title).to.eql(pm.collectionVariables.get("listingTitle"));
});
pm.collectionVariables.set("listingId", listing.id);

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Created listing is listed as pending", () => {
  const mine = pm.response.json().find(l => l.id === Number(pm.collectionVariables.get("listingId")));
  pm.expect(mine).to.exist;
  pm.expect(mine.status).to.eql("pending");
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Queue contains the new listing", () => {
  pm.expect(pm.response.json().map(l => l.id)).to.include(Number(pm.collectionVariables.get("listingId")));
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
const l = pm.response.json();
pm.test("Listing is rejected with the reason and reviewer", () => {
  pm.expect(l.status).to.eql("rejected");
  pm.expect(l.rejection_reason_choice).to.eql("Incomplete details");
  pm.expect(l.reviewed_by).to.be.a("number");
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Listing is pending again", () => {
  pm.expect(pm.response.json().status).to.eql("pending");
  pm.expect(pm.response.json().rejection_reason_choice).to.be.null;
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
const results = pm.response.json();
pm.test("Only the approved listing is returned and is verified", () => {
  pm.expect(results).to.have.lengthOf(1);
  pm.expect(results[0].id).to.eql(Number(pm.collectionVariables.get("listingId")));
  pm.expect(results[0].verified).to.be.true;
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Details show price and no reviews yet", () => {
  const l = pm.response.json();
  pm.expect(l.price_per_night).to.eql("320.00");
  pm.expect(l.reviews).to.eql([]);
});

pm.test("Status code is 201", () => pm.response.to.have.status(201));
const b = pm.response.json();
pm.test("Booking is pending and total is 3 x 320.00", () => {
  pm.expect(b.status).to.eql("pending");
  pm.expect(parseFloat(b.total_price)).to.eql(960);
});
pm.collectionVariables.set("bookingId", b.id);

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Booking is listed as pending without a review", () => {
  const mine = pm.response.json().find(b => b.id === Number(pm.collectionVariables.get("bookingId")));
  pm.expect(mine).to.exist;
  pm.expect(mine.status).to.eql("pending");
  pm.expect(mine.has_review).to.be.false;
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
pm.test("Request is listed with the listing title", () => {
  const r = pm.response.json().find(b => b.id === Number(pm.collectionVariables.get("bookingId")));
  pm.expect(r).to.exist;
  pm.expect(r.listing_title).to.eql(pm.collectionVariables.get("listingTitle"));
});

pm.test("Status code is 200", () => pm.response.to.have.status(200));
const open = pm.response.json().find(b => b.status === "completed" && !b.has_review);
pm.test("A completed stay without a review exists (run python manage.py init first)", () => pm.expect(open).to.exist);
if (open) {
  pm.collectionVariables.set("completedBookingId", open.id);
  pm.collectionVariables.set("completedListingId", open.listing_id);
}

